struct Expr {
    kind: ExprKind,
    span: Span,
}

enum ExprKind {
    Lit(i64),
    Binary(Box<Expr>, BinOp, Box<Expr>),
    If(Box<Expr>, Vec<Expr>),
}

impl Expr {
    fn children(&self) -> Vec<&Expr> {
        match &self.kind {
            ExprKind::Lit(_) => Vec::new(),
            ExprKind::Binary(l, _, r) => vec![l, r],
            ExprKind::If(c, body) => std::iter::once(&**c).chain(body).collect(),
        }
    }
}
